widget.solution:
def npv(rate, flows):
    return sum(c / (1 + rate) ** t for t, c in enumerate(flows))

def irr(flows):
    """Rate in [0, 1] where npv(rate, flows) is zero."""
    lo, hi = 0.0, 1.0
    while hi - lo > 1e-10:
        mid = (lo + hi) / 2
        if npv(mid, flows) > 0:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2
